import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = list(csv.reader(io.StringIO(raw_csv, newline=""),
                              delimiter=",", quotechar='"', doublequote=True))

    expected_width = 5
    header_index = next(
        (i for i, record in enumerate(records)
         if len(record) == expected_width and any(value.strip() for value in record)),
        None,
    )
    if header_index is None:
        header_index = next(
            (i for i, record in enumerate(records)
             if any(value.strip() for value in record)),
            None,
        )
    if header_index is None:
        return {"columns": [], "rows": []}

    columns = records[header_index][:]
    rows = records[header_index + 1:]
    width = max(expected_width, len(columns), max(map(len, rows), default=0))

    used_names = set(columns)
    suffix = 1
    while len(columns) < width:
        name = f"EXTRA_{suffix}"
        suffix += 1
        if name not in used_names:
            columns.append(name)
            used_names.add(name)

    return {
        "columns": columns,
        "rows": [row + [""] * (width - len(row)) for row in rows],
    }
